(() => {
  'use strict';
  if(globalThis.ThinkstarShowGrades||globalThis.ThinkstarGradeReady===false){document.getElementById('app').innerHTML=ThinkstarGradeScreen();return;}
  const teacherPreview=!!globalThis.ThinkstarTeacherPreview;
  const grade=globalThis.ThinkstarGrade||5, historyKey=globalThis.ThinkstarKey?.('thinkstar-history-v1')||'thinkstar-history-v1';
  const M=DrawerMissions,L=DrawerLogic,P=DrawerProgress,G=DrawerScoring,A=DrawerActivities,X=DrawerExplore,E=DrawerExploreUI,e=A.esc,app=document.getElementById('app');
  const basicTotal=M.filter(m=>!m.spicy).length,spicyTotal=M.filter(m=>m.spicy).length;
  const siteURL=location.origin+location.pathname;
  const catalog=globalThis.DrawerGrade5Catalog||[], audit=globalThis.DrawerLegacyAudit||[];
  const mythics=globalThis.ThinkstarMythic?.missions||[], allFriends=[...catalog,...mythics];
  const tastes={mild:'순한맛',medium:'보통맛',spicy:'매운맛',mythic:'신화급'};
  const taste=m=>m.difficulty||audit.find(r=>r.id===m.id)?.difficulty||'medium';
  const levelLabel=m=>m.mythic?'신화의 시험':/^grade[3-6]$/.test(m.edition)?(m.isExtension?'더 탐구':'기본 도전'):'이전 서랍';
  const names={safe:'도토리',lunch:'콩이',notice:'토리',shape:'곰곰이',robot:'로비',picture:'냥이',pattern:'도토리',science:'곰곰이',life:'토리'};
  const S={view:'home',taste:'all',page:0,showAll:false,time:5,all:false,spicy:false,category:'전체',mission:null,index:0,answers:[],feedback:'',good:false,seconds:0,history:[]};
  let token=0,focusBack=null,tick=performance.now(),lastCheckpoint=0;
  try{const h=JSON.parse(localStorage.getItem(historyKey)||'[]');if(Array.isArray(h))S.history=h.filter(r=>M.some(m=>m.id===r.id)&&Number.isFinite(r.seconds)&&r.seconds>=0).slice(-30);}catch{}
  const missionIds=M.map(m=>m.id);
  let localStore=null;try{localStore=window.localStorage;}catch{}
  let passInfo=P.load(localStore,missionIds),completionSaved=false;
  const passed=id=>(passInfo.state.missions[id]?.count||0)>0;
  const passedCount=()=>M.filter(m=>passed(m.id)).length;
  const passDate=at=>at?new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'short',day:'numeric'}).format(new Date(at)):'이전 버전에서 통과';
  const current=()=>S.mission?.steps[S.index],answer=()=>S.answers[S.index];
  let hero=0;try{hero=Number(localStorage.getItem('thinkstar-hero-v1'))===1?1:0;}catch{}
  const helper=(f,cls='')=>`<span class="hero-art ${cls}" data-level="${growth().level}" style="--hero-hue:${growth().hue}deg;background-position:${hero?100:0}% 0" role="img" aria-label="${hero?'루미':'카이'}"></span>`;
  function header(){return `<header><button class="brand" data-action="home"><span class="star-brand">←</span>맵으로 돌아가기</button><div class="header-right"><a class="grade-switch" href="?">${grade}학년 · 학년 바꾸기</a>${teacherPreview?'<b>교사용 미리보기</b>':levelBadge()}${globalThis.ThinkstarMusic?.available()?`<button class="text-button" data-action="music">${ThinkstarMusic.label()}</button>`:""}<button class="record-button" data-action="collection">내 친구 <b>${allFriends.filter(m=>passed(m.id)).length}/${allFriends.length}</b></button><button class="text-button" data-action="teacher">선생님 안내</button></div></header>`;}
  const growth=()=>ThinkstarGrowth(allFriends.filter(m=>passed(m.id)).length);
  function levelBadge(){const g=growth();return `<span class="level-badge" title="새 친구마다 경험치 10 · 다음 레벨까지 ${g.need-g.progress} EXP"><b>Lv.${g.level}</b><span>${g.progress}/${g.need} EXP</span><i style="--progress:${g.progress/g.need*100}%"></i></span>`;}
  const retryLeft=id=>Math.max(0,(record(id)?.study?.retryAt||0)-Date.now());
  function remaining(id){const secs=Math.ceil(retryLeft(id)/1000);return `${Math.floor(secs/60)}분 ${String(secs%60).padStart(2,'0')}초`;}
  function cooldown(id){const m=M.find(m=>m.id===id);modal('친구가 잠시 쉬고 있어요',`<div class="encounter-focus">${sprite(m,!passed(id),'large')}<p>이 친구에게는 <b data-retry="${id}">${remaining(id)}</b> 뒤 다시 도전할 수 있어요.</p><p>다른 지대의 친구를 만나며 탐험을 이어가요.</p><button class="primary" data-action="home">다른 친구 만나러 가기</button></div>`);}
  function failed(){const m=S.mission;return `<main class="wrap"><section class="done-panel failed-panel">${sprite(m,!passed(m.id),'celebrate')}<p class="eyebrow">이번에는 봉인을 풀지 못했어요</p><h1>잠시 쉬고, 다시 만나요.</h1><p>오답 3회로 이번 도전이 끝났어요.<br>이 친구는 <b data-retry="${m.id}">${remaining(m.id)}</b> 뒤 다시 만날 수 있어요.</p><p>이미 모은 친구와 경험치는 그대로예요.</p>${m.mythic?'':`<details class="failed-learning"><summary>방금 문제, 함께 살펴봐요</summary><p>${e(current()?.solution||'')}</p></details>`}<button class="primary" data-action="home">다른 친구 만나러 가기</button></section></main>`;}
  function footer(){return '<footer class="bottom-note"><span>창용쌤 제작</span></footer>';}
  const duration=s=>s<60?`${Math.floor(s)}초`:`${Math.floor(s/60)}분 ${Math.floor(s%60)}초`;
  const record=id=>passInfo.state.missions[id];
  const active=()=>record(S.mission?.id)?.study?.active;
  const status=r=>!r?'기록 없음':r.status==='complete'?'완료':r.status==='failed'?'획득 실패':r.status==='stopped'?'다시 시작 전':'진행 중';
  function sync(){const disk=P.load(localStore,missionIds);if(passInfo.available&&disk.available)passInfo=disk;}
  function commit(result){if(!result.ok){stale();return false;}passInfo.state=result.state;passInfo.available=P.save(localStore,passInfo.state);return true;}
  function stale(){token++;S.view='home';render();modal('다른 창에서 기록이 바뀌었어요','<p>이 도전이 다른 창에서 끝났거나 새로 시작됐어요. 서랍을 다시 열어 현재 기록부터 이어가 주세요.</p>');}
  function checkpoint(){if(S.view!=='activity')return;sync();commit(P.checkpoint(passInfo.state,S.mission.id,S.runToken,{index:S.index,answers:S.answers,seconds:S.seconds},missionIds));}
  function deduct(kind,key){sync();const result=P.charge(passInfo.state,S.mission.id,S.runToken,kind,S.index+':'+key,missionIds);if(!commit(result))return null;if(result.failed){S.view='failed';token++;render();window.scrollTo(0,0);}return result;}
  function penaltyText(result,kind){if(!result)return '';if(kind!=='wrong')return '도움을 살펴보고 차근차근 다시 생각해요. ';return result.changed?`남은 기회 ${Math.max(0,3-result.run.wrong)}번. `:'같은 답은 다시 실패로 세지 않아요. ';}
  function wrongText(q,a,collect=false){return penaltyText(deduct('wrong',G.fingerprint(q,a,collect)),'wrong');}
  function scoreRules(){return '<ul class="score-rules"><li>한 친구의 도전 전체에서 오답 3회면 이번 획득에 실패해요.</li><li>실패한 친구는 10분 뒤 다시 도전해요. 다른 친구에는 바로 도전할 수 있어요.</li><li>빈칸과 같은 오답의 반복 확인, 빈 답안 확인은 기회를 쓰지 않아요.</li><li>새 친구를 처음 얻으면 경험치 10! 2레벨은 80 EXP, 이후 필요한 경험치가 20씩 늘어요.</li><li>1레벨 1마리, 2레벨 2마리, 3레벨부터 3마리 동행해요. 도감에서 언제든 바꿀 수 있어요.</li></ul>';}
  function scoreStrip(){const r=active();return r?`<div class="chance-strip"><strong aria-label="남은 기회 ${Math.max(0,3-r.wrong)}번">${[0,1,2].map(i=>`<span class="${i<3-r.wrong?'':'used'}" aria-hidden="true">♥</span>`).join('')} <small>남은 기회 ${Math.max(0,3-r.wrong)}번</small></strong><button class="text-button" data-action="score-rules">도전 규칙</button></div>${!passInfo.available?'<p class="save-warning">저장할 수 없어 이 창에서만 기록이 유지돼요.</p>':''}`:'';}
  function cardScore(m){const r=record(m.id);return `<div class="card-score"><b>${retryLeft(m.id)?'잠시 쉬는 중 · '+remaining(m.id):r?.study?.active?'이어서 도전할 수 있어요':passed(m.id)?'이미 나의 친구예요':'성공하면 경험치 +10'}</b><span>${r?.study?.attempts||0}회 도전</span></div>`;}
  function recentResume(){const list=M.filter(m=>record(m.id)?.study?.active);return list.length?`<section class="resume-list"><h2>이어 하던 도전</h2>${list.map(m=>`<div class="resume-bar"><span><b>${e(m.title)}</b><small>${record(m.id).study.active.number}번째 도전</small></span><button class="secondary" data-action="resume" data-id="${m.id}">이어서 하기</button></div>`).join('')}</section>`:'';}
  function card(m){const own=passed(m.id);return `<button class="quest-card" data-action="start" data-id="${m.id}"><div class="card-top"><span>${e(m.subject)}</span><span class="taste-pill ${taste(m)}">${tastes[taste(m)]}</span></div><div class="quest-art">${sprite(m,!own)}<span>${own?'✓ 만난 친구':'도전 완료 후 만나요'}</span></div><h3>${e(m.title)}</h3><p>${e(m.desc)}</p><div class="quest-bottom">${own?e(m.friendName)+'와 다시 도전':'친구 만나러 가기'} <b>→</b></div></button>`;}
  function preview(m){const f=m.family;let content='';if(['lunch','life'].includes(f))content='<div class="mini-fractions"><i></i><i></i><i></i><i></i><i></i><i></i></div><b class="mini-question">?</b>';else if(['notice','science'].includes(f))content='<div class="mini-page"><i></i><i></i><i></i><span>✓</span></div><div class="mini-tag">단서</div>';else if(['shape'].includes(f))content='<div class="mini-tiles">'+Array.from({length:12},(_,i)=>`<i class="tile-${i%4}"></i>`).join('')+'</div>';else content='<div class="mini-cards"><i>2</i><i>?</i><i>6</i></div><span class="mini-path"></span>';const drawings={
 'g5-train':'<div class="mini-train"><i>2</i><b>─</b><i>6</i><b>─</b><i>?</i></div>',
 'g5-grid-paint':'<div class="mini-grid">'+Array.from({length:20},(_,i)=>`<i class="${i<8?'painted':''}"></i>`).join('')+'</div>',
 'g5-card-lock':'<div class="mini-cards"><i>1</i><i>3</i><i>5</i><i>8</i></div>',
 'g5-balance':'<div class="mini-balance"><i>?</i><i>2</i><i>7</i><i>4</i><i>6</i><i>3</i></div>',
 'g5-garden-int':'<div class="mini-garden"><i></i><i></i><i></i><i></i></div><span class="mini-tag">20m</span>',
 'g5-truth-clue':'<div class="mini-truth"><i>○</i><i>×</i><i>?</i><i>×</i><i>○</i><i>○</i></div>',
 'g5-budget-bundle':'<div class="mini-cards"><i>₩</i><i>?</i></div><span class="mini-tag">2,000</span>',
 'g5-plant-fair':'<div class="mini-pots"><i>♧</i><i>♧</i></div><span class="mini-tag">비교</span>'
 };content=drawings[m.id]||content;return `<div class="puzzle-preview preview-${f}" aria-hidden="true">${content}${helper(f,'card-helper')}</div>`;}

  function sprite(m,hidden=false,cls=''){if(m.mythic)return `<img class="mythic-art ${hidden?'silhouette':''} ${cls}" src="${e(m.art)}" alt="${hidden?'봉인된 신화급 친구':e(m.friendName)}">`;const i=m.friend%12,atlases=['collection-creatures','creatures-forest','creatures-ice','creatures-harbor','creatures-stars'];return `<span class="spirit spirit-${taste(m)} ${hidden?'silhouette':''} ${cls}" data-friend="${m.friend}" data-difficulty="${taste(m)}" style="--atlas:url('assets/${atlases[Math.floor(m.friend/12)]}.png');--sx:${i%4/3*100}%;--sy:${Math.floor(i/4)/2*100}%" role="img" aria-label="${hidden?'아직 만나지 않은 친구':e(m.friendName)}"></span>`;}
  function collectionStrip(){const own=allFriends.filter(m=>passed(m.id));return `<div class="collection-strip"><button class="text-button" data-action="collection">✦ 나의 친구 <b>${own.length}/${allFriends.length}</b></button><div class="mini-friends">${own.length?own.slice(-5).map(m=>sprite(m,false,'tiny')).join(''):'<span>도전을 마치면 이곳에 친구가 합류해요.</span>'}</div></div>`;}
  function garden(){return `<div class="garden" aria-label="나의 수집 정원"><div class="garden-label">나의 생각별 정원 <b>${allFriends.filter(m=>passed(m.id)).length} / ${allFriends.length}</b></div><div class="garden-friends">${allFriends.map(m=>`<button class="garden-slot" data-action="friend" data-id="${m.id}" aria-label="${passed(m.id)?e(m.friendName):'아직 만나지 않은 친구'} · ${e(m.title)}">${sprite(m,!passed(m.id))}<small>${passed(m.id)?e(m.friendName):'?'}</small></button>`).join('')}</div></div>`;}
  let collectionRegion=0;
  function collection(){const zones=globalThis.ThinkstarWorld?.zones||[{label:'햇살 초원'},{label:'안개 숲'},{label:'얼음 유적'},{label:'노을 항구'},{label:'별빛 관측소'}];modal('나만의 친구들',`<button class="secondary" data-action="party">동행 친구 바꾸기 · 현재 ${growth().capacity}마리</button><p>내 친구 ${passedCount()}/${allFriends.length} · ${levelBadge()}</p><nav class="collection-tabs" aria-label="도감 지대">${zones.map((z,i)=>`<button class="secondary" data-action="collection-region" data-value="${i}" aria-pressed="${collectionRegion===i}">${z.label} ${catalog.filter(m=>(m.region||0)===i&&passed(m.id)).length}/12</button>`).join('')}</nav><div class="friend-grid">${allFriends.filter(m=>(m.region||0)===collectionRegion).map(m=>`<button class="friend-tile" data-action="friend" data-id="${m.id}">${sprite(m,!passed(m.id))}<b>${passed(m.id)?e(m.friendName):'아직 만나지 않은 친구'}</b><small>${e(m.subject)} · ${tastes[taste(m)]}</small></button>`).join('')}</div>`,true);}
  let partySlot=0;
  function party(){
    const ids=ThinkstarParty.get(allFriends,passed),own=allFriends.filter(m=>passed(m.id));partySlot=Math.min(partySlot,ids.length-1);
    modal('함께 갈 친구를 골라요',`<p>Lv.${growth().level} · ${growth().capacity}마리까지 함께 걸어요. 2레벨에 두 번째, 3레벨에 세 번째 자리가 열려요.</p><div class="party-slots">${ids.map((id,i)=>{const m=allFriends.find(m=>m.id===id);return `<div><button class="party-slot" data-action="party-slot" data-value="${i}" aria-pressed="${partySlot===i}">${m?sprite(m,false,'large'):'<span class="empty-party">＋</span>'}<b>${i+1}번 자리 · ${m?e(m.friendName):'비어 있어요'}</b></button>${m?`<button class="text-button" data-action="party-remove" data-value="${i}">정원에서 쉬기</button>`:''}</div>`}).join('')}</div><p class="party-message" role="status">${partySlot+1}번 자리에 함께할 친구를 골라요.</p><div class="party-roster">${own.map(m=>`<button class="friend-tile" data-action="party-choose" data-id="${m.id}">${sprite(m,false)}<b>${e(m.friendName)}</b><small>${ids.includes(m.id)?'동행 중':'함께 걷기'}</small></button>`).join('')||'<p>도전을 마치면 친구를 만날 수 있어요.</p>'}</div><button class="primary" data-action="party-done">이 친구들과 출발!</button>`,true);
  }
  function replacePet(){
    const m=S.mission;if(!m||!passed(m.id))return;
    const ids=ThinkstarParty.get(allFriends,passed);
    if(ids.includes(m.id)){modal('이미 함께 걷고 있어요',`<p>${e(m.friendName)}는 나의 동행이에요.</p><button class="primary" data-action="close-modal">좋아요</button>`);return;}
    modal('펫을 교체하시겠습니까?',`<div class="replace-new">${sprite(m,false,'large')}<b>새 친구 · ${e(m.friendName)}</b></div><p>함께할 자리를 골라요. 쉬는 친구는 도감에 그대로 남아요.</p><div class="party-slots">${ids.map((id,i)=>{const old=allFriends.find(c=>c.id===id);return `<button class="party-slot" data-action="replace-pet-slot" data-value="${i}">${old?sprite(old,false,'large'):'<span class="empty-party">＋</span>'}<b>${old?e(old.friendName)+' 대신 데려가기':'빈자리에 데려가기'}</b></button>`}).join('')}</div><button class="secondary" data-action="close-modal">지금 친구들과 갈래요</button>`);
  }
  function rewardParty(){
    const m=S.mission,ids=globalThis.ThinkstarParty?.get(allFriends,passed)||[];
    return ids.includes(m.id)?'<p class="reward-party-note">이 친구가 함께 걷고 있어요. 동행은 도감에서 바꿀 수 있어요.</p>':'<div class="reward-party-note"><b>펫을 교체하시겠습니까?</b><button class="secondary" data-action="replace-pet">새 친구 데려가기</button></div>';
  }
  function friend(id){const m=M.find(m=>m.id===id);if(!m)return;modal(passed(id)?m.friendName:'어떤 친구가 기다릴까요?',`<div class="friend-detail">${sprite(m,!passed(id),'large')}<h3>${e(m.title)}</h3><p>${passed(id)?e(m.friendDesc):e(m.desc)}</p><p>${tastes[taste(m)]} · ${e(m.subject)}</p>${cardScore(m)}<button class="primary" data-action="start" data-id="${id}">${passed(id)?'한 번 더 도전':'이 친구 만나러 가기'}</button></div>`);}
  function visual(q){if(S.mission.id==='g3-26')return globalThis.ThinkstarGradeDiagrams?.render(S.mission.id,q,S.index)||'';if(q.visual?.type==='cards'&&/국어/.test(S.mission.subject)&&!q.visual.items.some(s=>/^\d+[행연][:：]/.test(s))){const concrete=globalThis.ThinkstarCasual?.render(S.mission,q,S.index,S.answers);const illustration=concrete?.replace(/<details[\s\S]*?<\/details>/g,'')||globalThis.ThinkstarScenes?.render(S.mission,q)||'';return `<div class="casual-visual reading-visual">${illustration}<article class="reading-passage" aria-label="읽을 글">${q.visual.items.map(s=>`<p>${e(s).replace(/\n/g,'<br>')}</p>`).join('')}</article></div>`;}if(q.visual?.type==='cards'&&q.visual.items.some(s=>/^\d+[행연][:：]/.test(s)))return `<figure class="poem-page"><figcaption>시를 천천히 읽어 봐요</figcaption>${q.visual.items.map(s=>`<p>${e(s.replace(/^\d+[행연][:：]\s*/,'')) .replace(/\n/g,'<br>')}</p>`).join('')}</figure>`;const concrete=globalThis.ThinkstarCasual?.render(S.mission,q,S.index,S.answers);if(concrete!=null)return concrete?`<div class="casual-visual">${concrete}</div>`:'';const base=visualBase(q),scene=globalThis.ThinkstarScenes?.render(S.mission,q)||'';return base.includes('class="visual-cards"')?`<div class="illustrated-clues">${scene}${base}</div>`:base&&globalThis.ThinkstarScenes?.worldRender(S.mission.id)&&!base.includes('world-lesson-scene')?`<div class="visual-diagram">${globalThis.ThinkstarScenes.worldRender(S.mission.id)}${base}</div>`:base||scene;}
  function visualBase(q){const diagram=globalThis.ThinkstarGradeDiagrams?.render(S.mission?.id,q,S.index);if(diagram)return diagram;if(q.visual?.type==='parts'){const v=q.visual;return `<figure class="parts-visual"><div class="parts-grid">${Array.from({length:v.total},(_,i)=>`<span class="${i<v.selected?'marked':''}"></span>`).join('')}</div><figcaption>똑같은 ${v.total}칸 · 색칠한 부분을 살펴봐요</figcaption></figure>`;}if(q.visual?.type==='cards')return `<div class="visual-cards" aria-label="문제 단서">${q.visual.items.map(v=>`<span>${e(v)}</span>`).join('')}</div>`;if(q.visual?.type==='bars'){const v=q.visual,max=Math.max(...v.values,1);return `<figure class="visual-bars study-bars" aria-label="문제 자료 막대그래프"><figcaption>자료를 비교해요 · ${e(v.unit||'수')}</figcaption>${v.labels.map((label,i)=>`<div class="visual-bar"><span>${e(label)}</span><b>${e(v.values[i])}${e(v.unit||'')}</b><div class="study-bar-track"><i style="width:${Math.max(0,v.values[i])/max*100}%"></i></div></div>`).join('')}<div class="study-scale"><span>0</span><span>${e(max)}${e(v.unit||'')}</span></div></figure>`;}const id=S.mission?.id||'';const extra=globalThis.ThinkstarPictures?.render(id,q,S.index);if(extra)return extra;if(id==='cs-map')return `<div class="map-example"><p>옆 칸으로 한 번 이동 = 100m</p><div class="map-nine">${Array.from({length:9},(_,i)=>`<span>${i===2?'📚 도서관':i===6?'🏫 학교':'·'}</span>`).join('')}</div><small>출발 칸은 세지 않아요.</small></div>`;if(id==='cs-library-guide')return '<div class="visual-chips"><span>회원증 먼저</span><span>최대 2권</span><span>7일 뒤 같은 요일까지</span><span>수요일 오후 반납함 닫힘</span></div>';if(id==='cs-witness-read')return '<div class="time-picture"><span>10:30~10:40<br><b>쉬는 시간 · 도서실 열림</b></span><span>10:40~11:20<br><b>3교시 · 전원 운동장</b><small>교실로 돌아간 학생 없음</small></span></div>';if(id==='cs-plant-fair')return '<div class="plant-picture"><div><span>☀</span><b>화분 ㄱ</b><i style="height:90px"></i><small>9cm · 밝은 곳</small></div><div><span>◐</span><b>화분 ㄴ</b><i style="height:40px"></i><small>4cm · 어두운 곳</small></div><p>가상 기록 · 10일 뒤 · 두 화분 모두 물 20mL/일</p></div>';return '';}

  function home(){return `<main class="wrap exploration-home">${teacherPreview?`<section class="teacher-preview-bar" aria-label="교사용 미리보기"><div><b>교사용 미리보기 · 모든 지대 열림</b><p>여기서 푼 기록은 학생 기록과 따로 저장돼요.</p></div><nav aria-label="미리볼 학년">${[3,4,5,6].map(g=>`<a href="?grade=${g}" aria-current="${g===grade?'page':'false'}">${g}학년</a>`).join('')}</nav><button class="secondary" data-action="teacher-preview-exit">미리보기 끝내기</button></section>`:''}${globalThis.ThinkstarWorld?ThinkstarWorld.html({catalog,allFriends,passed,hero,sprite,helper,retryLeft,regionOpen,regionNotice,bossPanel}):catalog.map(card).join('')}${!passInfo.available?'<p class="save-warning">기기에 저장할 수 없어 현재 창에서만 친구와 기록이 유지돼요.</p>':''}${recentResume()}${footer()}</main>`;}
  function regionOpen(region){return !region||!globalThis.ThinkstarGate||ThinkstarGate(catalog,passed).open;}
  function regionNotice(){const g=ThinkstarGate(catalog,passed);modal('새로운 지대로 가는 길',`<p>${globalThis.ThinkstarEntryWorld?.name||'첫 지대'}에서 친구 <b>${g.need}명</b>을 만나면 다른 지대가 열려요.</p><p>지금 ${g.done}/${g.need}명 · ${Math.max(0,g.need-g.done)}명 더 만나면 출발!</p><button class="primary" data-action="close-modal">첫 지대에서 더 탐험하기</button>`);}
  function bossPanel(region){const m=mythics.find(m=>m.region===region);if(!m)return '';const g=ThinkstarMythic.progress(m,catalog,passed),own=passed(m.id);if(teacherPreview)g.open=true;return `<section class="mythic-shrine ${g.open?'ready':''}" aria-label="신화의 성역">${sprite(m,!own)}<div class="mythic-shrine-copy"><p class="eyebrow">✦ 지대의 마지막 이야기 · 신화급</p><h2>${own?e(m.friendName)+'와 맺은 약속':g.open?'신화의 봉인이 반응해요!':'열두 친구가 깨우는 신화'}</h2><p>${own?'이제 도감에서 함께 걸을 수 있어요.':g.open?'매운맛 너머, 세 가지 시험에 도전해요.':'이 지대의 친구를 모두 만나면 마지막 시험이 열려요.'}</p><progress value="${g.done}" max="12" aria-label="신화 도전 개방"></progress> <span>${g.done}/12 친구</span></div>${g.open?`<button class="primary" data-action="start" data-id="${m.id}">${own?'신화의 친구 만나기':'신화의 시험에 도전'}</button>`:''}</section>`;}
  const revealKey=globalThis.ThinkstarKey?.('thinkstar-mythic-reveals-v1')||'thinkstar-mythic-reveals-v1';
  const revealed=new Set();try{const saved=JSON.parse(localStore?.getItem(revealKey)||'[]');if(Array.isArray(saved))saved.filter(id=>mythics.some(m=>m.id===id)).forEach(id=>revealed.add(id));}catch{}
  function milestone(region){
    const key=ThinkstarKey('thinkstar-eight-'+region);
    try{if(localStore?.getItem(key))return;localStore?.setItem(key,'1');}catch{}
    const boss=mythics.find(m=>m.region===region);
    modal('신화의 봉인이 반짝여요!',`<div class="milestone-focus">${boss?sprite(boss,true,'large'):''}<h2>친구 8마리를 만났어요!</h2><p>4마리만 더 모으면 <strong>신화급 친구</strong>에게 도전할 수 있어요.</p><button class="primary" data-action="close-modal">나머지 친구 만나러 가기</button></div>`);
  }
  function revealMythic(region){const m=mythics.find(m=>m.region===region);if(!m||passed(m.id)||revealed.has(m.id)||!ThinkstarMythic.progress(m,catalog,passed).open)return false;
    modal('신화의 봉인이 깨어났어요!',`<div class="mythic-arrival"><p class="eyebrow">열두 친구의 마음이 하나로!</p><div class="mythic-arrival-stage"><span class="mythic-rays" aria-hidden="true"></span><span class="mythic-orbit" aria-hidden="true"></span>${Array.from({length:12},(_,i)=>`<i class="mythic-spark" style="--angle:${i*30}deg;--delay:${i*.06}s" aria-hidden="true">✦</i>`).join('')}${sprite(m,true,'large')}</div><h2>신화의 친구가<br>당신을 기다려요!</h2><p>이 지대의 친구 12명을 모두 구했어요.<br>매운맛을 넘어서는 마지막 시험에 도전해 볼까요?</p><button class="primary" data-action="start" data-id="${m.id}">신화의 친구 만나기 ✦</button><button class="text-button" data-action="close-modal">지금은 친구들과 기뻐할래요</button></div>`);
    document.querySelector('.modal')?.classList.add('mythic-arrival-modal');revealed.add(m.id);try{localStore?.setItem(revealKey,JSON.stringify([...revealed]));}catch{}return true;
  }
  function guardRegion(m){if(!teacherPreview&&m.mythic&&!ThinkstarMythic.progress(m,catalog,passed).open){modal('열두 친구의 힘이 필요해요',bossPanel(m.region));return false;}if(regionOpen(m.region)||record(m.id)?.study?.active)return true;regionNotice();return false;}
  function start(id){
    const m=M.find(x=>x.id===id);if(!m)return;if(m.isExtension&&!passed(m.parentId)){modal('기본 도전부터 열어요','<p>기본 도전을 해결한 뒤 더 탐구할 수 있어요.</p>');return;}sync();if(!guardRegion(m))return;if(retryLeft(id)){cooldown(id);return;}const run=record(id)?.study?.active,own=passed(id);
    modal(own?'친구를 다시 만났어요':m.mythic?'신화의 봉인이 깨어났어요':'봉인된 친구를 발견했어요',`<div class="encounter-focus">${sprite(m,!own,'large')}<p class="encounter-level">${tastes[taste(m)]}(${e(m.subject)})</p>${!passInfo.available?'<p class="save-warning">이 기기에서는 기록이 저장되지 않아요.</p>':''}<div class="start-actions"><button class="primary" data-action="${run?'resume':'begin'}" data-id="${id}">도전 시작</button><button class="secondary" data-action="close-modal">둘러볼래요</button></div></div>`);
    document.querySelector('.modal')?.classList.add('encounter-modal');document.querySelector('.modal')?.setAttribute('data-taste',taste(m));if(m.mythic)document.querySelector('.modal')?.classList.add('mythic-modal');
  }
  function enterQuest(id){
    const m=M.find(x=>x.id===id);if(!m)return;sync();if(!guardRegion(m))return;if(retryLeft(id)){cooldown(id);return;}
    globalThis.ThinkstarSound?.play('enter');
    if(globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches){begin(id);return;}
    const kind=m.mythic?'mythic':taste(m)==='spicy'?'spicy':'first';
    const file=kind==='first'?'first-quest-portal':kind+'-quest-portal';
    const title=kind==='mythic'?'신화의 봉인이 깨어나요':kind==='spicy'?'성역의 시험이 시작돼요':'친구의 봉인을 풀러 가요!';
    modal(title,`<div class="quest-portal ${kind}"><video muted playsinline autoplay preload="auto" aria-label="${title}" src="assets/video/${file}.mp4"></video><p>${title}</p><button class="primary portal-skip">바로 도전하기</button></div>`);
    const video=document.querySelector('.quest-portal video');let ended=false;
    function proceed(){if(ended||!video?.isConnected)return;ended=true;begin(id);}
    video?.addEventListener('ended',proceed,{once:true});video?.addEventListener('error',proceed,{once:true});
    document.querySelector('.portal-skip')?.addEventListener('click',proceed,{once:true});
    video?.play()?.catch(proceed);setTimeout(proceed,8000);
  }
  function begin(id,restart=false){const m=M.find(x=>x.id===id);if(!m)return;sync();if(!guardRegion(m))return;if(retryLeft(id)){cooldown(id);return;}if(m.isExtension&&!passed(m.parentId)){start(id);return;}const result=P.begin(passInfo.state,id,{token:crypto.randomUUID(),at:new Date().toISOString(),restart},missionIds);if(!commit(result))return;const r=result.run,snap=r.snapshot;completionSaved=false;token++;Object.assign(S,{view:'activity',mission:m,index:Math.min(snap?.index||0,m.steps.length-1),answers:m.steps.map((q,i)=>({...L.fresh(q),...((!q.revision||snap?.answers[i]?.revision===q.revision)?(snap?.answers[i]||{}):snap?.answers[i]?.passed?{passed:true}:{}),revision:q.revision,running:false})),feedback:'',good:false,seconds:snap?.seconds||0,runToken:r.token});tick=performance.now();closeModal();render();document.querySelector('.active-collection')?.classList.add('quest-arrival');window.scrollTo(0,0);}

  function aside(){const m=S.mission;return `<aside class="side"><div class="companion">${helper(m.family)}<div><b>${names[m.family]||'친구'}와 생각하기</b><p>놓아보고, 바꿔보고,<br>내 생각을 확인해요.</p></div></div><div class="aside-box"><h2>오늘 발견할 것</h2><p>${e(m.skill)}</p></div><div class="aside-box"><h2>미리 알면 좋아요</h2><p>${e(m.prereq)}</p><button class="text-button" data-action="instructions">규칙·사용 방법 · 무료</button></div><div class="aside-box itinerary"><h2>${levelLabel(m)}의 발자국</h2><ol>${m.steps.map((q,i)=>`<li class="${i===S.index?'now':''} ${S.answers[i].passed?'passed':''}"><button data-action="go-step" data-value="${i}" ${i>S.index&&!S.answers.slice(0,i).every(a=>a.passed)?'disabled':''}>${S.answers[i].passed?'✓':i+1} ${e(q.phase||'생각하기')}</button></li>`).join('')}</ol><p>언제든 멈췄다 이어가도 괜찮아요.</p></div></aside>`;}
  function activity(){const q=current(),a=answer(),m=S.mission;return `${collectionStrip()}<main class="wrap ${m.color} active-collection"><div class="activity-head"><div class="activity-title"><span class="tag">${m.category}</span><h1>${m.title}</h1></div><button class="text-button" data-action="stop">수집 포기</button></div><div class="journey"><span>봉인 해제 ${S.index+1}단계</span><div class="progress-track" role="progressbar" aria-label="도전 진행" aria-valuemin="0" aria-valuemax="${m.steps.length}" aria-valuenow="${S.answers.filter(x=>x.passed).length}"><i style="width:${100*S.answers.filter(x=>x.passed).length/m.steps.length}%"></i></div><span class="quest-difficulty ${taste(m)}"><b>${tastes[taste(m)]}</b> · ${e(m.subject)}</span></div>${scoreStrip()}<div class="activity-layout"><section class="puzzle-panel" data-type="${q.type}"><div class="step-nav"><button class="text-button" data-action="previous" ${S.index===0?'disabled':''}>이전 생각</button></div>${A.render(['cs-library-space','cs-weather','cs-budget-bundle'].includes(m.id)?{...q,table:undefined}:q,a).replace(/(<p class="task-desc">[\s\S]*?<\/p>)/,part=>part+visual(q))}${S.feedback?`<div class="feedback ${S.good?'good':''}" role="status">${e(S.feedback)}</div>`:''}<div class="actionbar"><span class="action-progress">봉인 해제 ${S.index+1}단계</span><button class="primary" data-action="${a.passed?'next':'check'}" ${a.running?'disabled':''}>${a.passed?(S.index===m.steps.length-1?'도전 마무리':'다음 생각'):(q.type==='write'?'내 생각 확인':'확인하기')}</button></div></section></div>${footer()}</main>`;}
  function doneScore(){const r=record(S.mission.id);return `<div class="done-score">${levelBadge()}<p>${r.count===1?'새 친구를 구해 경험치 +10!':'다시 도전해도 경험치는 중복으로 오르지 않아요.'}</p><p>${r.study?.attempts||r.count}번째 도전 · 오답 ${r.study?.latest?.wrong||0}회</p>${r.count===1&&ThinkstarGrowth(passedCount()).level>ThinkstarGrowth(passedCount()-1).level?`<div class="level-up-look"><h2>✦ Lv.${growth().level} 레벨 업!</h2>${helper('','level-up-hero')}<p>탐험가의 빛과 장식이 달라졌어요! · 동행 ${growth().capacity}마리</p></div>`:'' }</div>`;}
  function done(){const m=S.mission,r=record(m.id);return `<main class="wrap"><div class="done-panel collection-done"><p class="eyebrow">${r.count===1?(m.mythic?'신화의 봉인 해제! 신화의 동료가 되었어요!':'봉인 해제! 새로운 동료가 되었어요!'):'친구와 한 번 더 성장했어요!'}</p><div class="seal-reveal ${r.count===1?'new-friend':''} ${m.mythic?'mythic-reward':''}">${m.mythic&&r.count===1?'<span class="mythic-rays" aria-hidden="true"></span><span class="mythic-orbit" aria-hidden="true"></span>'+Array.from({length:12},(_,i)=>`<i class="mythic-spark" style="--angle:${i*30}deg;--delay:${i*.06}s" aria-hidden="true">✦</i>`).join(''):''}<span class="seal-halo" aria-hidden="true">✦</span>${sprite(m,false,'celebrate')}</div><h1>${r.count===1?'반가워, ':'다시 만나 반가워, '}${e(m.friendName)}!</h1><p>${e(m.friendDesc)}</p><div class="collection-count">✦ 친구 ${allFriends.filter(m=>passed(m.id)).length} / ${allFriends.length}</div>${rewardParty()}${doneScore()}<div class="reflection"><b>오늘의 발견</b><p>${e(m.summary)}</p></div><div class="done-actions"><button class="primary" data-action="home">맵으로 돌아가기</button><button class="text-button" data-action="records">도전 기록</button></div><p class="small">${passInfo.available?'이 기기에 친구와 기록을 저장했어요.':'저장할 수 없어 현재 창에서만 유지돼요.'} 같은 친구는 중복으로 늘어나지 않아요.</p></div></main>`;}
  function render(){globalThis.ThinkstarMusic?.update(globalThis.ThinkstarWorld?.currentRegion?.()||0,S.view);document.querySelector('.correct-burst')?.remove();globalThis.ThinkstarWorld?.unmount();if(S.view==='activity'){checkpoint();if(S.view!=='activity')return;}app.innerHTML=header()+(S.view==='home'?home():S.view==='activity'?activity():S.view==='done'?done():S.view==='failed'?failed():`<main class="wrap"><div class="rest">${helper('notice','done-helper')}<h1>여기까지, 잘 마쳤어요.</h1><p>화면을 내려두고 다음 수업을 준비해요.</p><button class="text-button" data-action="home">다음 활동 시간에 친구 만나기</button></div></main>`);if(S.view==='home')globalThis.ThinkstarWorld?.mount(app,{catalog,allFriends,passed,hero,sprite,helper,onEncounter:start,onRegion:render,retryLeft,regionOpen,regionNotice});}
  function focusTask(){window.scrollTo(0,0);document.querySelector('.task-title')?.focus({preventScroll:true});}
  function feedback(text,good=false){S.feedback=text;S.good=good;render();document.querySelector('.feedback')?.scrollIntoView({block:'nearest'});}
  function mutate(){answer().passed=false;S.answers.slice(S.index+1).forEach(a=>a.passed=false);S.feedback='';S.good=false;}
  function modal(title,html,wide=false){focusBack=document.activeElement;document.getElementById('modal-root').innerHTML=`<div class="modal-shade"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${e(title)}" tabindex="-1"><div class="modal-top"><h2>${title}</h2><button class="secondary" data-action="close-modal">닫기</button></div>${html}</section></div>`;app.inert=true;document.querySelector('.modal').focus();}
  function closeModal(){document.getElementById('modal-root').innerHTML='';app.inert=false;if(focusBack?.isConnected)focusBack.focus();focusBack=null;}
  function pause(){if(S.view==='activity'){token++;answer().running=false;checkpoint();}}
  function finish(){if(!S.answers.every(a=>a.passed)){S.index=S.answers.findIndex(a=>!a.passed);feedback('아직 확인하지 않은 단계가 있어요. 차례로 살펴봐요.');return;}if(completionSaved)return;sync();const result=P.finish(passInfo.state,S.mission.id,S.runToken,{at:new Date().toISOString(),helped:S.answers.some(a=>a.hint>0||a.solutionUsed),selfChecked:S.mission.steps.some(q=>q.type==='write')},missionIds);if(!commit(result))return;completionSaved=true;globalThis.ThinkstarSound?.play(S.mission.mythic?'mythic':'capture');if(record(S.mission.id).count===1){globalThis.ThinkstarParty?.add(S.mission.id,allFriends,passed);globalThis.ThinkstarWorld?.rescue(S.mission.id);}S.view='done';token++;S.history=[...S.history,{id:S.mission.id,seconds:Math.floor(S.seconds)}].slice(-30);try{localStore.setItem(historyKey,JSON.stringify(S.history));}catch{}render();window.scrollTo(0,0);if(!S.mission.mythic){const region=S.mission.region||0;if(catalog.filter(m=>(m.region||0)===region&&passed(m.id)).length===8&&record(S.mission.id).count===1)milestone(region);else revealMythic(region);}}

  function correctEffect(selfCheck=false){
    if(!selfCheck)globalThis.ThinkstarSound?.play('correct');
    document.querySelector('.correct-burst')?.remove();
    const effect=document.createElement('div');effect.className='correct-burst';effect.setAttribute('role','status');
    effect.innerHTML=`<span aria-hidden="true">✦</span><b>${selfCheck?'생각 확인 완료!':'정답이에요!'}</b><small>봉인의 빛이 한 걸음 더 밝아졌어요</small>`;
    document.body.append(effect);setTimeout(()=>effect.remove(),1600);
  }
  function check(){const q=current(),a=answer();if(L.valid(q,a,S.answers[S.index-1])){a.passed=true;feedback(q.type==='write'?'내 기록을 스스로 확인했어요. 앞뒤가 잘 연결되는지 한 번 읽어봐요.':q.solution,true);correctEffect(q.type==='write');return;}
    if(S.mission.mythic){if(!G.ready(q,a)){feedback('아직 답을 다 준비하지 않았어요. 기회를 쓰지 않고 이어서 해봐요.');return;}const note=wrongText(q,a);if(S.view==='activity')feedback('아직 정답이 아니에요. '+note);return;}
    if(X.is(q)){if(!G.ready(q,a)){feedback(X.pending(q,a)+' 기회를 쓰지 않고 이어서 해봐요.');return;}const note=wrongText(q,a);if(S.view==='activity')feedback(note+X.explain(q,a,S.answers[S.index-1]));return;}
    const msg={crossword:'1~9를 한 번씩 놓고, 가로 세 식과 세로 세 합이 모두 맞는지 확인해요.',order:'모든 카드를 순서대로 놓고, 앞 단계가 끝난 뒤 다음 행동을 할 수 있는지 살펴보세요.',choice:'보기를 하나 고르고 조건과 다시 비교해 보세요.',multi:'빠진 보기나 조건에 맞지 않는 보기가 있는지 하나씩 살펴보세요.',numbers:'모든 칸에 수를 적고 계산을 다시 확인해 보세요.',grid:'전체를 같은 크기로 나누어 생각해 보세요. 색칠한 칸 수를 다시 확인해요.',cards:q.all?'조건에 맞는 서로 다른 번호를 모두 모아보세요.':'카드를 모두 놓고 조건을 하나씩 확인해 보세요.',shape:q.rule?'빈칸과 겹침을 확인하고, 정해진 A 조각 조건도 확인해 보세요.':'네 조각을 빈칸과 겹침 없이 모두 놓아보세요.',write:'각 칸에 서로 다른 내용을 짧은 문장으로 적고, 아래 확인 항목도 살펴주세요.',robot:'먼저 명령을 실행해요. 도착 위치와 바꾼 명령 수, 다른 경로 조건을 확인하세요.'};if(q.type==='write'){feedback(msg[q.type]+' 글의 내용은 자동 채점하지 않으며 기회를 쓰지 않아요.');return;}if(!G.ready(q,a)){feedback('아직 답을 다 준비하지 않았어요. 기회를 쓰지 않고 이어서 해봐요. '+msg[q.type]);return;}const note=wrongText(q,a);if(S.view==='activity')feedback(note+msg[q.type]);}
  function solution(){const q=current(),result=deduct('solutions','view');if(!result)return;answer().solutionUsed=true;S.feedback=result.changed?penaltyText(result,'solutions'):'풀이를 다시 보는 것은 기회를 쓰지 않아요.';S.good=false;render();let more='';if(q.type==='shape'){const p=L.solveShape(q),map={};for(const [k,v]of Object.entries(p||{}))L.cells(v).forEach(c=>map[c.join(',')]=k);more=`<div class="solution-tiling" style="grid-template-columns:repeat(${q.w},1fr)">${Array.from({length:q.w*q.h},(_,i)=>`<span class="piece-${map[[i%q.w,Math.floor(i/q.w)].join(',')]}">${map[[i%q.w,Math.floor(i/q.w)].join(',')]||'·'}</span>`).join('')}</div><p>이 배치 말고도 맞는 답이 있을 수 있어요. 내 손으로 다시 놓아봐요.</p>`;}modal('풀이를 함께 살펴봐요',`<p>${e(q.solution)}</p>${more}<p class="small">도움 받은 뒤 내 방식으로 확인해 보세요.</p>`);}
  function notebook(){const m=S.mission;modal('내 생각 모아보기',`<p>${m.title} · 이 창에서 작성한 기록이에요.</p>${m.steps.map((q,i)=>{const a=S.answers[i];if(q.type==='write'&&a.values.some(x=>x.trim()))return `<article class="notebook"><h3>${e(q.title)}</h3>${q.fields.map((f,j)=>`<b>${e(f)}</b><p>${e(a.values[j]||'아직 쓰지 않았어요.').replace(/\n/g,'<br>')}</p>`).join('')}</article>`;if(!a.passed)return '';if(X.is(q))return `<article class="notebook"><h3>${i+1}. ${e(q.title)}</h3><p>${e(E.summary(q,a))}</p><p>${e(q.solution)}</p></article>`;return `<article class="notebook"><h3>${i+1}. ${e(q.title.replace(/^\d+\. /,''))}</h3><p>${e(q.solution)}</p></article>`;}).join('')||'<p>생각을 기록하거나 단계를 마치면 여기에 모여요.</p>'}<p class="small">진행 중인 답안은 이 기기에만 저장해 이어가고, 도전을 마치거나 새로 시작하면 저장된 답안은 지워요. 다른 곳으로 보내지 않아요.</p>`,true);}
  function recordDetail(m){const r=record(m.id),d=r.study;return `<article class="pass-item"><span class="pass-seal">${r.count?'✓':'…'}</span><div class="pass-content"><h3>${e(m.title)}</h3><p>${r.count?'친구 획득 완료':'아직 도전 중'} · ${d?.attempts||0}회 도전</p>${retryLeft(m.id)?`<p>다시 만나기까지 <b data-retry="${m.id}">${remaining(m.id)}</b></p>`:''}<details><summary>도전 발자국</summary><ol>${[...(d?.recent||[]),...(d?.active?[d.active]:[])].map(x=>`<li>${x.number}회차 · ${x.status==='failed'?'획득 실패':status(x)} · 오답 ${x.wrong}회</li>`).join('')}</ol></details></div></article>`;}
  function records(){sync();const entries=allFriends.filter(m=>record(m.id));modal('나의 도전 기록',`<p>친구 ${allFriends.filter(m=>passed(m.id)).length}/${allFriends.length}</p><p class="small">이 기기·브라우저에 저장해요. 공동 기기에서는 함께 쌓이고, 브라우저 데이터를 삭제하면 사라져요.</p>${entries.length?entries.map(recordDetail).join(''):'<p>첫 만남을 기다리고 있어요.</p>'}`,true);}
  function teacher(){modal('선생님 안내',`<section class="teacher-preview-help"><h3>모든 맵 미리보기</h3><p>수업 전에 모든 지대와 신화급 문제를 살펴볼 수 있어요. 학생 기록은 그대로 유지됩니다.</p><button class="primary" data-action="${teacherPreview?'teacher-preview-exit':'teacher-preview-open'}">${teacherPreview?'미리보기 끝내기':'교사용 미리보기 열기'}</button></section><h3>${grade}학년 다했어요! 모험도감</h3><p>다섯 지대에 12개씩, 기본 60개 도전·180단계가 있습니다. 각 지대의 친구 12명을 모두 모으면 신화급 시험 1개가 열려요. 추가 시험 5개·15단계로 신화급 친구 5종을 만날 수 있습니다.</p><p>난이도는 학년 안에서의 상대 기준입니다. 순한맛은 직접 관찰·기본 개념, 보통맛은 여러 조건 연결, 매운맛은 경우 나누기·복합 추론 중심입니다. 아직 배우지 않은 개념은 제시 자료와 교과서를 함께 살펴보게 해 주세요.</p><p>도전의 모든 단계를 해결하면 정해진 친구를 얻습니다. 재도전으로 중복 획득하지 않습니다.</p>${scoreRules()}<p>새로고침과 이어하기는 같은 회차입니다. 획득한 친구·도전 횟수·오답·재도전 대기 시간을 기록합니다. 맵으로 돌아가도 답안과 남은 기회가 유지됩니다.</p><p>이 기기·브라우저에만 저장하며 공동 기기에서는 기록을 공유합니다. 학생별 계정·동기화는 없습니다. 기존 서랍과는 별도 저장 공간입니다.</p><p>실제 학생의 소요시간과 학습효과는 아직 측정하지 않았습니다. 문제 풀이의 시간 제한·공개 순위·뽑기는 없습니다. 실패 후 10분 대기는 해당 친구에게만 적용합니다.</p><button class="secondary" data-action="records">도전 기록 보기</button>`,true);}
  function legacy(){modal('이전 서랍',`<p>예전 기록은 그대로예요. 새 화면에 맞춰 다시 구성할 문제는 새 도전 목록에서 쉬고 있어요.</p><div class="legacy-list">${M.filter(m=>!/^grade[3-6]$/.test(m.edition)).map(m=>{const r=audit.find(r=>r.id===m.id),active=record(m.id)?.study?.active;return `<article><div><b>${e(m.title)}</b><small>${r?.status==='keep'?'다시 열 수 있어요':e(r?.reason||'검토 중')}</small></div>${active?`<button class="secondary" data-action="resume" data-id="${m.id}">이어서 하기</button>`:r?.status==='keep'?`<button class="secondary" data-action="start" data-id="${m.id}">열기</button>`:'<span class="small">기록 보존</span>'}</article>`;}).join('')}</div>`,true);}
  function instructions(){const q=current();const guides={combo:'＋와 −로 묶음 수를 바꿔요. 순서만 다른 같은 묶음은 같은 방법이에요. 모으기는 답을 확인하는 버튼이에요.',chain:'카드를 순서대로 눌러 연결해요. 놓인 카드를 누르면 뺄 수 있어요. 모으기는 답을 확인하는 버튼이에요.',cards:'숫자 카드를 눌러 빈칸에 놓아요. 놓인 카드를 누르면 뺄 수 있어요. 모으기는 답을 확인하는 버튼이에요.',grid:'칸을 누르면 칠해지고, 다시 누르면 지워져요. 칸을 바꾸는 동안은 기회를 쓰지 않아요.',place:'놓을 자리를 고른 뒤 숫자 카드를 눌러요. 모든 조건을 살펴본 뒤 확인해요.',truth:'후보마다 각 말이 참인지 거짓인지 표시하고 조건에 맞는 후보를 골라요.',open:'조건에 맞는 수를 각 칸에 넣어요. 여러 답이 가능한 문제는 조건을 만족하는 다른 답도 인정해요.',robot:'방향 명령을 놓고 실행해 보세요. 실행과 수정은 무료예요. 마지막 확인만 평가해요.',order:'카드를 실행할 순서대로 눌러요. 놓은 카드를 누르면 빼서 바꿀 수 있어요.',multi:'조건에 맞는 보기를 모두 선택해요. 다시 누르면 선택이 풀려요.',write:'내 생각을 짧게 적고 확인 항목을 살펴요. 글의 내용은 자동으로 채점하지 않아요.'};modal('사용 방법 · 무료',`<p>${e(guides[q.type]||'문제의 조건을 살펴보고 답을 준비해요. 답을 골랐다면 확인하기를 눌러요.')}</p><p>규칙과 사용 방법은 몇 번을 봐도 기회를 쓰지 않아요. 생각 도움과 풀이도 기회를 쓰지 않아요.</p>`);}
  function printSolution(q){
    if(q.type==='shape'){const p=L.solveShape(q),map={};for(const [k,v] of Object.entries(p||{}))L.cells(v).forEach(c=>map[c.join(',')]=k);return '<pre>'+Array.from({length:q.h},(_,y)=>Array.from({length:q.w},(_,x)=>map[[x,y].join(',')]||'·').join(' ')).join('\n')+'</pre>';}
    return q.type==='robot'&&q.example?'<p>한 가지 경로: '+q.example.map(d=>A.arrows[d]).join(' ')+'</p>':'';
  }
  function printable(m){let output=`<article><p>다했어요! 모험도감 · 창용쌤</p><h1>${m.title}</h1><p>${levelLabel(m)} · ${e(m.skill)}</p></article>`;output+=m.steps.map((q,i)=>`<section class="print-step"><h2>${i+1}. ${e(q.title.replace(/^\d+\. /,''))}</h2><p>${e(q.prompt)}</p>${q.document?`<blockquote>${q.document.lines.map(e).join('<br>')}</blockquote>`:''}${q.image?`<img class="print-picture" src="${q.image}" alt="관찰 그림">`:''}${A.dataReference(q)}${X.is(q)?E.print(q):''}${q.type==='crossword'?A.crossword(null,true):''}${q.type==='order'?`<p>아래 카드에 실행 순서를 숫자로 써 보세요.</p><ul>${q.items.map(t=>`<li>(　) ${e(t)}</li>`).join('')}</ul>`:''}${q.options?`<ol>${q.options.map(x=>`<li>□ ${e(x)}</li>`).join('')}</ol>`:''}${q.conditions?`<p>카드: ${q.digits.join(', ')}<br>${q.conditions.map(e).join('<br>')}</p>`:''}${q.type==='grid'?`<pre>${Array.from({length:q.total/q.cols},()=>Array(q.cols).fill('□').join(' ')).join('\n')}</pre>`:''}${q.type==='shape'?`<p>세 칸짜리 ㄴ 조각 네 개. ${e(q.rule?.text||'')}</p><pre>${Array.from({length:q.h},()=>Array(q.w).fill('□').join(' ')).join('\n')}</pre>`:''}${q.type==='robot'?`<p>출발: ${q.start[1]+1}행 ${q.start[0]+1}열 / 도착: ${q.goal[1]+1}행 ${q.goal[0]+1}열<br>처음 명령: ${q.initial.map(d=>A.arrows[d]).join(' ')}<br>막힌 칸: ${q.blocks.map(([x,y])=>`${y+1}행 ${x+1}열`).join(', ')||'없음'}<br>${q.maxChanges==null?'자유롭게 바꾸기':q.maxChanges+'장만 바꾸기'}</p><pre>${Array.from({length:q.h},()=>Array(q.w).fill('□').join(' ')).join('\n')}</pre>`:''}${(q.fields||[]).map(f=>`<p>${e(f)}</p><div class="print-line"></div>`).join('')}${q.checks?`<p>${q.checks.map(t=>'□ '+e(t)).join('<br>')}</p>`:''}</section>`).join('');output+=`<article class="answer-page"><h1>도움과 해설</h1>${m.steps.map((q,i)=>`<section><h2>${i+1}. ${e(q.title.replace(/^\d+\. /,''))}</h2><p>${e(q.solution)}</p>${printSolution(q)}</section>`).join('')}</article>`;return output;}
  async function run(){const q=current(),a=answer();if(a.running)return;mutate();const serial=++token,result=L.robotPath(q,a.commands);a.running=true;a.ran=false;a.robotIndex=0;a.commandIndex=null;render();for(let i=1;i<result.path.length;i++){await new Promise(r=>setTimeout(r,matchMedia('(prefers-reduced-motion: reduce)').matches?60:280));if(serial!==token||S.view!=='activity')return;a.robotIndex=i;render();}if(serial!==token)return;a.running=false;a.ran=true;feedback(!result.valid?`${result.reason}에 닿았어요. 그 칸에 들어가기 전 명령을 살펴봐요.`:result.arrived?'목적지에 도착했어요. 확인하기를 눌러 조건도 살펴봐요.':'목적지와 지금 위치를 비교해서 명령을 고쳐보세요.',result.valid&&result.arrived);}
  document.addEventListener('input',ev=>{if(ev.target.matches('[data-field]')&&S.view==='activity'){answer().values[Number(ev.target.dataset.field)]=ev.target.value;mutate();const b=document.querySelector('[data-action="next"]');if(b){b.dataset.action='check';b.textContent=current().type==='write'?'내 생각 확인':'확인하기';}document.querySelector('.feedback')?.remove();checkpoint();}});
  document.addEventListener('change',ev=>{if(ev.target.matches('[data-check]')){const n=Number(ev.target.dataset.check),a=answer();a.checks=ev.target.checked?[...new Set([...a.checks,n])]:a.checks.filter(x=>x!==n);mutate();render();}});
  document.addEventListener('keydown',ev=>{const dialog=document.querySelector('.modal');if(!dialog)return;if(ev.key==='Escape'){ev.preventDefault();closeModal();return;}if(ev.key==='Tab'){const elements=[...dialog.querySelectorAll('button,input,select,textarea,a,summary')].filter(x=>!x.disabled),first=elements[0],last=elements.at(-1);if(ev.shiftKey&&(document.activeElement===first||document.activeElement===dialog)){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}});
  document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;const act=b.dataset.action,v=b.dataset.value;
    if(act==='close-modal'){closeModal();return;}
    if(act==='teacher'){teacher();return;}
    if(act==='teacher-preview-open'){modal('교사용 미리보기 열기','<p>모든 학년의 지대와 문제를 열어 살펴봅니다. 미리보기 기록은 학생 기록과 따로 저장돼요.</p><label for="preview-code">선생님 확인 번호</label><input id="preview-code" type="password" inputmode="numeric" maxlength="4" autocomplete="off"><p id="preview-error" role="status"></p><button class="secondary" data-action="teacher">돌아가기</button> <button class="primary" data-action="teacher-preview-confirm">모든 맵 열기</button>');return;}
    if(act==='teacher-preview-confirm'){if(document.getElementById('preview-code')?.value!=='5522'){document.getElementById('preview-error').textContent='선생님 확인 번호를 확인해 주세요.';return;}try{sessionStorage.setItem('thinkstar-teacher-preview','1');location.assign('?grade='+grade);}catch{document.getElementById('preview-error').textContent='이 브라우저에서는 미리보기를 열 수 없어요. 일반 창에서 다시 시도해 주세요.';}return;}
    if(act==='teacher-preview-exit'){try{sessionStorage.removeItem('thinkstar-teacher-preview');location.assign('?grade='+grade);}catch{modal('미리보기 종료','<p>이 탭을 닫고 새 탭에서 다시 접속해 주세요.</p>');}return;}

    if(act==='legacy'){legacy();return;}
    if(act==='instructions'&&S.view==='activity'){instructions();return;}
    if(act==='taste'){S.taste=v;S.page=0;render();return;}
    if(act==='shuffle-shelf'){S.page=(S.page+1)%2;render();return;}
    if(act==='catalog-all'){S.showAll=!S.showAll;S.taste='all';S.page=0;render();return;}
    if(act==='records'){records();return;}
    if(act==='score-rules'){modal('도전 규칙',scoreRules()+'<p class="small">새로 시작해도 첫 도전과 횟수는 남아요. 속도 경쟁 없이 내 생각을 확인해요.</p>');return;}
    if(act==='spicy'){S.spicy=!S.spicy;S.all=false;S.category='전체';render();return;}
    if(act==='copy'){try{await navigator.clipboard.writeText(siteURL);const t=document.getElementById('toast');t.textContent='주소를 복사했어요.';t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2000);}catch{modal('주소를 복사해 주세요',`<input aria-label="도전 서랍 주소" readonly value="${siteURL}">`);}return;}
    if(act==='clear-history'){modal('선생님용 기록 초기화','<p>이 브라우저의 모든 도전 횟수·수집 기록·재도전 대기과 진행 중인 답안을 지웁니다. 공동 기기라면 함께 쌓인 기록도 삭제됩니다.</p><label for="reset-code">선생님 확인 번호</label><input id="reset-code" type="password" inputmode="numeric" maxlength="4" autocomplete="off"><p id="reset-error" role="status"></p><button class="secondary" data-action="teacher">기록 유지하기</button> <button class="primary" data-action="confirm-clear">모든 기록 초기화</button>');return;}
    if(act==='confirm-clear'){if(document.getElementById('reset-code')?.value!=='5522'){document.getElementById('reset-error').textContent='선생님 확인 번호를 확인해 주세요.';return;}const cleared=P.erase(localStore);if(!cleared.available){document.getElementById('reset-error').textContent='저장소에 접근할 수 없어 기록을 지우지 못했어요.';return;}S.history=[];passInfo=cleared;token++;S.view='home';render();teacher();return;}

    if(act==='print'){const m=M.find(x=>x.id===document.getElementById('print-mission').value);let sheet=document.getElementById('print-sheet');if(!sheet){sheet=document.createElement('div');sheet.id='print-sheet';document.body.append(sheet);}sheet.innerHTML=printable(m);window.print();return;}
    if(act==='hero'){hero=Number(v)===1?1:0;try{localStorage.setItem('thinkstar-hero-v1',String(hero));}catch{}render();return;}
    if(act==='collection'){collection();return;}
    if(act==='collection-region'){collectionRegion=Math.max(0,Math.min(4,Number(v)||0));collection();return;}
    if(act==='replace-pet'){replacePet();return;}
    if(act==='replace-pet-slot'){if(S.mission)ThinkstarParty.setSlot(Number(v),S.mission.id,allFriends,passed);closeModal();render();return;}
    if(act==='party'){partySlot=0;party();return;}
    if(act==='party-slot'){partySlot=Math.max(0,Math.min(2,Number(v)||0));party();return;}
    if(act==='party-choose'){ThinkstarParty.setSlot(partySlot,b.dataset.id,allFriends,passed);party();return;}
    if(act==='party-remove'){ThinkstarParty.setSlot(Number(v),null,allFriends,passed);party();return;}
    if(act==='party-done'){closeModal();render();return;}
    if(act==='friend'){friend(b.dataset.id);return;}
    if(act==='home'){pause();S.view='home';closeModal();render();window.scrollTo(0,0);return;}
    if(act==='start'){start(b.dataset.id);return;}
    if(act==='music'){ThinkstarMusic.toggle();b.textContent=ThinkstarMusic.label();return;}
    if(act==='begin'){enterQuest(b.dataset.id);return;}
    if(act==='resume'){enterQuest(b.dataset.id);return;}

    if(act==='time'){S.time=Number(v);S.spicy=false;S.all=false;S.category='전체';render();return;}
    if(act==='category'){S.category=v;render();return;}
    if(act==='all'){S.spicy=false;S.all=!S.all;S.category='전체';render();return;}
    if(act==='stop'){modal('수집을 그만할까요?','<p>지금은 맵으로 돌아가요. 답안과 남은 기회는 그대로 남아, 다시 만나면 이어서 도전해요.</p><button class="primary" data-action="home">수집 포기</button><button class="secondary" data-action="close-modal">계속 도전</button>');return;}
    if(act==='rest'){pause();closeModal();S.view='rest';render();window.scrollTo(0,0);return;}
    if(act==='notebook'){notebook();return;}
    if(S.view!=='activity')return;const q=current(),a=answer();
    if(act==='zoom-image'){modal('그림을 자세히 살펴봐요',`<img class="zoomed-picture" src="${q.image}" alt="${e(q.alt)}">`,true);return;}
    if(act==='hint'){if(a.hint<2){const result=deduct('hints',String(a.hint+1));if(!result)return;a.hint++;S.feedback=penaltyText(result,'hints');S.good=false;render();document.querySelector('.hint-body')?.scrollIntoView({block:'nearest'});}else solution();return;}
    if(act==='previous'||act==='go-step'){const target=act==='previous'?S.index-1:Number(v);if(target>=0&&target<S.mission.steps.length&&(target<=S.index||S.answers.slice(0,target).every(x=>x.passed))){token++;a.running=false;S.index=target;S.feedback='';render();focusTask();}return;}
    if(act==='next'){if(!a.passed)return;if(S.index===S.mission.steps.length-1)finish();else{S.index++;S.feedback='';S.good=false;render();focusTask();}return;}
    if(act==='check'){check();return;}
    if(a.running)return;
    if(X.is(q)&&E.handle(act,b,q,a,{mutate,render,feedback,wrong:()=>wrongText(q,a,true),alive:()=>S.view==='activity'}))return;
    if(act==='cross-slot'){a.crossIndex=Number(v);render();return;}
    if(act==='cross-digit'){const n=Number(v);if(a.cross.includes(n))return;mutate();a.cross[a.crossIndex]=n;const next=a.cross.indexOf(null);if(next>=0)a.crossIndex=next;render();return;}
    if(act==='cross-clear'){mutate();a.cross[a.crossIndex]=null;render();return;}
    if(act==='run'){run();return;}
    if(act==='option'){mutate();const n=Number(v);if(q.type==='multi')a.selected=a.selected.includes(n)?a.selected.filter(x=>x!==n):[...a.selected,n];else a.choice=n;render();return;}
    if(act==='order-add'){if(q.type!=='order'||a.order.includes(Number(v)))return;mutate();a.order.push(Number(v));render();return;}
    if(act==='order-remove'){if(q.type!=='order')return;mutate();a.order=a.order.filter(n=>n!==Number(v));render();return;}
    if(act==='order-reset'){if(q.type!=='order')return;mutate();a.order=[];render();return;}
    if(act==='cell'){mutate();const n=Number(v);a.selected=a.selected.includes(n)?a.selected.filter(x=>x!==n):[...a.selected,n];render();return;}
    if(act==='digit'){mutate();const i=a.slots.indexOf(null);if(i>=0&&!a.slots.includes(Number(v)))a.slots[i]=Number(v);render();return;}
    if(act==='slot'){mutate();a.slots[Number(v)]=null;render();return;}
    if(act==='collect'){mutate();const n=Number(a.slots.join(''));if(a.slots.includes(null)){feedback('먼저 카드를 모두 놓아주세요.');return;}if(!q.answers.includes(n)){const note=wrongText(q,a,true);if(S.view==='activity')feedback(note+'이 번호는 맞지 않는 조건이 있어요. 단서를 하나씩 확인해요.');return;}if(a.found.includes(n)){feedback('이미 모은 번호예요. 다른 번호를 찾아봐요.');return;}a.found.push(n);a.slots.fill(null);feedback('조건에 맞는 번호를 모았어요.',true);return;}
    if(act==='piece'){a.piece=v;a.rotation=a.placements[v]?.r||0;render();return;}
    if(act==='rotate'){a.rotation=(a.rotation+1)%4;render();return;}
    if(act==='remove-piece'){mutate();delete a.placements[a.piece];render();return;}
    if(act==='place'){const cells=L.rotate(a.rotation),anchor=cells.find(p=>p[1]===0),p={x:Number(b.dataset.x)-anchor[0],y:Number(b.dataset.y),r:a.rotation};if(L.canPlace(q,a.placements,a.piece,p)){mutate();a.placements[a.piece]=p;const next=L.names.find(k=>!a.placements[k]);if(next){a.piece=next;a.rotation=0;}render();}else feedback('겹치거나 간판 밖으로 나갔어요. 흰 점의 위치나 방향을 바꿔봐요.');return;}
    if(act==='command'){a.commandIndex=Number(v);render();return;}
    if(act==='direction'){if(a.commandIndex===null)return;mutate();a.commands[a.commandIndex]=v;a.commandIndex=null;a.robotIndex=0;a.ran=false;render();return;}
    if(act==='robot-reset'){mutate();a.commands=q.initial.slice();a.commandIndex=null;a.robotIndex=0;a.ran=false;render();return;}
  });
  setInterval(()=>{document.querySelectorAll('[data-retry]').forEach(el=>el.textContent=remaining(el.dataset.retry));const now=performance.now(),delta=(now-tick)/1000;tick=now;if(S.view==='activity'&&!document.hidden){S.seconds+=Math.min(delta,2);if(now-lastCheckpoint>5000){checkpoint();lastCheckpoint=now;}}},1000);
  document.addEventListener('visibilitychange',()=>{tick=performance.now();checkpoint();});
  window.addEventListener('pagehide',checkpoint);
  window.addEventListener('storage',ev=>{if(ev.key===P.key){if(S.view==='activity'){sync();if(active()?.token!==S.runToken)stale();else render();}else{sync();render();}}});
  try{const mc=document.modelContext;if(mc?.registerTool){const lifecycle=new AbortController();const tools=[{name:'list_drawer_activities',title:'생각별 활동 목록',description:`List catalog and legacy activities with difficulty, extension status and step counts; read only.`,inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({activities:M.map(({id,title,difficulty,isExtension,edition,steps,category})=>({id,title,difficulty,isExtension:!!isExtension,edition:edition||"legacy",steps:steps.length,category}))})},{name:'start_drawer_activity',title:'생각별 활동 시작',description:'Open the creature encounter start dialog from the home screen. A new attempt is counted only when the user confirms. Does not submit answers or complete steps.',inputSchema:{type:'object',properties:{activityId:{type:'string',enum:M.map(x=>x.id)}},required:['activityId'],additionalProperties:false},execute:({activityId})=>{if(!M.some(m=>m.id===activityId))throw Error('Unknown activityId');if(S.view==='activity')throw Error('Leave the current activity first.');start(activityId);return {activity:M.find(m=>m.id===activityId).title,startConfirmation:true};}}];tools.forEach(t=>Promise.resolve(mc.registerTool(t,{signal:lifecycle.signal})).catch(()=>{}));}}catch{}
  render();
})();

